(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const $ = id => document.getElementById(id);
  const ui = { intro:$('intro'), level:$('levelOverlay'), end:$('endOverlay'), pause:$('pauseToast'), hud:$('hud'), health:$('healthFill'), healthText:$('healthText'), xp:$('xpFill'), xpText:$('xpText'), timer:$('timer'), levelText:$('level'), kills:$('kills'), toast:$('toast'), pauseBtn:$('pauseBtn'), mobile:$('mobileControls') };
  const TAU = Math.PI * 2, GOAL = 180, WORLD = 3000;
  let W=innerWidth,H=innerHeight,DPR=1, last=0, raf, soundOn=false, audio;
  let state='menu', elapsed=0, spawnClock=0, attackClock=0, hitClock=0, dashClock=0, kills=0, level=1, xp=0, xpNeed=8, upgrades=[], projectiles=[], enemies=[], gems=[], particles=[], foliage=[];
  const keys = new Set(), touchMove={x:0,y:0}, player={x:0,y:0,vx:0,vy:0,r:17,hp:100,maxHp:100,speed:210,damage:24,range:370,fireRate:.72,shots:1,magnet:105,invuln:0,face:1,dashPower:1};
  const upgradesCatalog=[
    {id:'thorns',icon:'⌁',tag:'ARMA · POTENCIA',name:'Espinas de hierro',desc:'Tus púas infligen un 35% más de daño.',apply:()=>player.damage*=1.35},
    {id:'swift',icon:'➶',tag:'ARMA · CADENCIA',name:'Viento afilado',desc:'Ataca un 22% más rápido.',apply:()=>player.fireRate*=.78},
    {id:'twins',icon:'✣',tag:'ARMA · MULTIDISPARO',name:'Doble espina',desc:'Lanza una púa adicional por ataque.',apply:()=>player.shots=Math.min(5,player.shots+1)},
    {id:'heart',icon:'♡',tag:'ESPÍRITU · VITALIDAD',name:'Corazón de roble',desc:'Recupera 30 de vida y aumenta tu máximo en 25.',apply:()=>{player.maxHp+=25;player.hp=Math.min(player.maxHp,player.hp+45)}},
    {id:'boots',icon:'⌑',tag:'ESPÍRITU · MOVIMIENTO',name:'Paso de ciervo',desc:'Aumenta tu velocidad un 17%.',apply:()=>player.speed*=1.17},
    {id:'moon',icon:'◉',tag:'ESPÍRITU · ATRACCIÓN',name:'Llamada lunar',desc:'Atrae los fragmentos de esencia desde más lejos.',apply:()=>player.magnet+=115},
    {id:'shell',icon:'⬡',tag:'ESPÍRITU · RESISTENCIA',name:'Corteza viva',desc:'Reduce el daño recibido y restaura 20 de vida.',apply:()=>{player.hp=Math.min(player.maxHp,player.hp+20);player.damageReduction=(player.damageReduction||0)+.12}}
  ];
  function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=Math.floor(W*DPR);canvas.height=Math.floor(H*DPR);canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(DPR,0,0,DPR,0,0)}
  addEventListener('resize',resize); resize();
  function seeded(n){let x=Math.sin(n*127.1+311.7)*43758.5453;return x-Math.floor(x)}
  function makeFoliage(){foliage=[];for(let i=0;i<260;i++){const x=seeded(i+5)*WORLD-WORLD/2,y=seeded(i+1000)*WORLD-WORLD/2;foliage.push({x,y,r:8+seeded(i+800)*22,c:Math.floor(seeded(i+1800)*4),a:.08+seeded(i+2222)*.12})}}
  makeFoliage();
  const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  function startGame(){
    state='playing';elapsed=0;spawnClock=.65;attackClock=.25;hitClock=0;dashClock=0;kills=0;level=1;xp=0;xpNeed=8;projectiles=[];enemies=[];gems=[];particles=[];
    Object.assign(player,{x:0,y:0,vx:0,vy:0,r:17,hp:100,maxHp:100,speed:210,damage:24,range:370,fireRate:.72,shots:1,magnet:105,invuln:0,face:1,dashPower:1,damageReduction:0});
    ['intro','level','end','pause'].forEach(id=>$(id).classList.add('hidden'));ui.hud.classList.remove('hidden');$('healthWrap').classList.remove('hidden');$('xpWrap').classList.remove('hidden');$('objective').classList.remove('hidden');$('weaponBadge').classList.remove('hidden');$('controlsHint').classList.remove('hidden');ui.pauseBtn.classList.remove('hidden');ui.mobile.classList.remove('hidden');updateHud(); toast('LA ESPESURA DESPIERTA'); playTone(440,.08);
  }
  function showMenu(){state='menu';ui.intro.classList.remove('hidden');ui.end.classList.add('hidden');ui.pause.classList.add('hidden');ui.hud.classList.add('hidden');['healthWrap','xpWrap','objective','weaponBadge','controlsHint'].forEach(id=>$(id).classList.add('hidden'));ui.pauseBtn.classList.add('hidden');ui.mobile.classList.add('hidden');const best=Number(localStorage.getItem('hollowgroveBest')||0);$('bestRun').querySelector('b').textContent=best?fmt(best):'—'}
  function fmt(t){const s=Math.floor(t);return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')}
  function updateHud(){ui.timer.textContent=fmt(elapsed);ui.levelText.textContent=String(level).padStart(2,'0');ui.kills.textContent=kills;ui.health.style.width=(player.hp/player.maxHp*100)+'%';ui.healthText.textContent=`${Math.ceil(player.hp)} / ${player.maxHp}`;ui.xp.style.width=(xp/xpNeed*100)+'%';ui.xpText.textContent=`${xp} / ${xpNeed}`;$('goalTime').textContent=fmt(Math.max(0,GOAL-elapsed))}
  function toast(msg){ui.toast.textContent=msg;ui.toast.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>ui.toast.classList.remove('show'),1600)}
  function playTone(freq=400,dur=.08){if(!soundOn)return;try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+dur);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+dur)}catch(_){}}
  function spawnEnemy(){const ang=Math.random()*TAU,dist=Math.max(W,H)*.62+50;const x=player.x+Math.cos(ang)*dist,y=player.y+Math.sin(ang)*dist;const t=elapsed;let type='mote';if(t>20&&Math.random()<.30)type='bat';if(t>45&&Math.random()<.25)type='brute';if(t>90&&Math.random()<.18)type='shroom';const scale=1+Math.min(t/200,.8);const config={mote:[11,30,74,'#b3c879'],bat:[9,22,112,'#bb89b1'],brute:[19,100,44,'#c28764'],shroom:[14,54,60,'#d7a552']};const [r,hp,speed,color]=config[type];enemies.push({x,y,r,hp:hp*scale,maxHp:hp*scale,speed:speed*(1+Math.min(t/340,.35)),type,color,phase:Math.random()*TAU,hit:0})}
  function spawnBoss(){const a=Math.random()*TAU;enemies.push({x:player.x+Math.cos(a)*500,y:player.y+Math.sin(a)*500,r:36,hp:1050,maxHp:1050,speed:37,type:'boss',color:'#cf7469',phase:0,hit:0,boss:true});toast('EL GUARDIÁN HUECO HA DESPERTADO');playTone(110,.35)}
  function update(dt){if(state!=='playing')return;elapsed+=dt;if(elapsed>=GOAL){elapsed=GOAL;finish(true);return}if(elapsed>=90&&!enemies.some(e=>e.boss)&&!window.bossDefeated){window.bossDefeated=true;spawnBoss()}if(elapsed<1)window.bossDefeated=false;
    let ix=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0)+touchMove.x;let iy=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0)+touchMove.y;const mag=Math.hypot(ix,iy);if(mag>1){ix/=mag;iy/=mag}player.vx=ix*player.speed;player.vy=iy*player.speed;if(ix)player.face=Math.sign(ix);player.x=clamp(player.x+player.vx*dt,-WORLD/2+45,WORLD/2-45);player.y=clamp(player.y+player.vy*dt,-WORLD/2+45,WORLD/2-45);player.invuln=Math.max(0,player.invuln-dt);dashClock=Math.max(0,dashClock-dt);hitClock=Math.max(0,hitClock-dt);
    spawnClock-=dt;const interval=Math.max(.27,1.08-elapsed*.0038);if(spawnClock<=0){spawnEnemy();if(elapsed>55&&Math.random()<.35)spawnEnemy();spawnClock=interval}
    attackClock-=dt;if(attackClock<=0&&enemies.length){let target=null,bd=player.range;for(const e of enemies){const d=Math.hypot(e.x-player.x,e.y-player.y);if(d<bd){bd=d;target=e}}if(target){const base=Math.atan2(target.y-player.y,target.x-player.x);for(let n=0;n<player.shots;n++){const off=(n-(player.shots-1)/2)*.12,a=base+off;projectiles.push({x:player.x+Math.cos(a)*19,y:player.y+Math.sin(a)*19,vx:Math.cos(a)*560,vy:Math.sin(a)*560,life:.8,r:5,damage:player.damage})}attackClock=player.fireRate;playTone(620,.045)}else attackClock=.12}
    for(let i=projectiles.length-1;i>=0;i--){const p=projectiles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;let hit=false;for(let j=enemies.length-1;j>=0;j--){const e=enemies[j];if(Math.hypot(p.x-e.x,p.y-e.y)<e.r+p.r){e.hp-=p.damage;e.hit=.12;hit=true;burst(p.x,p.y,'#e6e9a1',3);if(e.hp<=0)killEnemy(j);break}}if(hit||p.life<=0)projectiles.splice(i,1)}
    for(let i=enemies.length-1;i>=0;i--){const e=enemies[i];e.hit=Math.max(0,e.hit-dt);e.phase+=dt*4;const a=Math.atan2(player.y-e.y,player.x-e.x);const wobble=e.type==='bat'?Math.sin(e.phase*2)*.4:0;e.x+=Math.cos(a+wobble)*e.speed*dt;e.y+=Math.sin(a+wobble)*e.speed*dt;if(Math.hypot(player.x-e.x,player.y-e.y)<player.r+e.r-3&&player.invuln<=0&&hitClock<=0){const harm=(e.boss?24:e.type==='brute'?18:11)*(1-(player.damageReduction||0));player.hp-=harm;player.invuln=.7;hitClock=.16;burst(player.x,player.y,'#ee987c',8);playTone(150,.12);if(player.hp<=0){player.hp=0;finish(false);return}}}
    for(let i=gems.length-1;i>=0;i--){const g=gems[i],d=Math.hypot(player.x-g.x,player.y-g.y);if(d<player.magnet){const pull=1+Math.max(0,(player.magnet-d)/player.magnet)*5;g.x+=(player.x-g.x)*Math.min(1,dt*pull*2.7);g.y+=(player.y-g.y)*Math.min(1,dt*pull*2.7)}if(d<player.r+g.r+5){gems.splice(i,1);xp+=g.value;burst(g.x,g.y,'#d9ed9b',7);playTone(760,.06);if(xp>=xpNeed)levelUp()}}
    for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.08,dt);p.vy*=Math.pow(.08,dt);p.life-=dt;if(p.life<=0)particles.splice(i,1)}
    updateHud();
  }
  function killEnemy(i){const e=enemies[i];enemies.splice(i,1);kills++;const value=e.boss?12:e.type==='brute'?3:1;for(let n=0;n<value;n++)gems.push({x:e.x+(Math.random()-.5)*18,y:e.y+(Math.random()-.5)*18,r:e.boss?5:4,value:e.boss?1:1,phase:Math.random()*TAU});burst(e.x,e.y,e.color,e.boss?25:9);if(e.boss){window.bossDefeated=true;toast('EL GUARDIÁN HA CAÍDO · +12 ESENCIA');for(let n=0;n<11;n++)gems.push({x:e.x+(Math.random()-.5)*50,y:e.y+(Math.random()-.5)*50,r:5,value:1,phase:Math.random()*TAU})}if(kills%10===0)toast(`${kills} ALMAS LIBERADAS`);}
  function burst(x,y,color,n){for(let i=0;i<n;i++){const a=Math.random()*TAU,s=20+Math.random()*150;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.25+Math.random()*.42,max:.5,color,r:1+Math.random()*2})}}
  function levelUp(){xp-=xpNeed;level++;xpNeed=Math.ceil(xpNeed*1.35+2);state='level';const pool=[...upgradesCatalog].sort(()=>Math.random()-.5).slice(0,3);const grid=$('upgradeGrid');grid.innerHTML='';pool.forEach(u=>{const card=document.createElement('button');card.className='upgrade-card';card.innerHTML=`<div class="upgrade-icon">${u.icon}</div><div><small>${u.tag}</small><strong>${u.name}</strong></div><p>${u.desc}</p>`;card.onclick=()=>{u.apply();state='playing';ui.level.classList.add('hidden');updateHud();toast(`MEJORA OBTENIDA · ${u.name.toUpperCase()}`);playTone(880,.16)};grid.appendChild(card)});ui.level.classList.remove('hidden');updateHud();playTone(540,.2)}
  function finish(win){state='end';ui.pauseBtn.classList.add('hidden');ui.mobile.classList.add('hidden');ui.level.classList.add('hidden');ui.end.classList.remove('hidden');$('endTitle').innerHTML=win?'El alba <em>llega.</em>':'La noche <em>vence.</em>'; $('endEyebrow').innerHTML=win?'<span></span> LA ÚLTIMA VIGILIA':'<span></span> LA ESPESURA TE RECLAMA';$('endDescription').textContent=win?'El bosque recordará tu nombre. Has resistido hasta el alba.':'El bosque guarda tu último aliento. Aún puedes volver.';$('endSymbol').textContent=win?'✦':'✳';$('resultTime').textContent=fmt(elapsed);$('resultKills').textContent=kills;$('resultLevel').textContent=level;const best=Number(localStorage.getItem('hollowgroveBest')||0);if(elapsed>best)localStorage.setItem('hollowgroveBest',Math.floor(elapsed));playTone(win?680:130,.4)}
  function pause(){if(state==='playing'){state='paused';ui.pause.classList.remove('hidden')}else if(state==='paused'){state='playing';ui.pause.classList.add('hidden')}}
  function draw(){ctx.setTransform(DPR,0,0,DPR,0,0);ctx.clearRect(0,0,W,H);const camX=player.x-W/2,camY=player.y-H/2;ctx.fillStyle='#1b2a1e';ctx.fillRect(0,0,W,H);drawGround(camX,camY);ctx.save();ctx.translate(-camX,-camY);for(const f of foliage){if(f.x<camX-50||f.x>camX+W+50||f.y<camY-50||f.y>camY+H+50)continue;drawFoliage(f)}for(const g of gems)drawGem(g);for(const p of projectiles)drawProjectile(p);for(const e of enemies)drawEnemy(e);drawPlayer();for(const p of particles){ctx.globalAlpha=clamp(p.life*2,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,TAU);ctx.fill()}ctx.globalAlpha=1;ctx.restore();if(state==='playing'&&player.invuln>0){ctx.fillStyle=`rgba(229,105,95,${.05+Math.sin(Date.now()/35)*.04})`;ctx.fillRect(0,0,W,H)} }
  function drawGround(cx,cy){ctx.fillStyle='#1b2a1e';ctx.fillRect(0,0,W,H);const size=80,ox=-((cx%size)+size)%size,oy=-((cy%size)+size)%size;ctx.strokeStyle='rgba(162,183,120,.045)';ctx.lineWidth=1;for(let x=ox;x<W;x+=size){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke()}for(let y=oy;y<H;y+=size){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}for(let i=0;i<foliage.length;i+=2){const f=foliage[i],x=f.x-cx,y=f.y-cy;if(x<0||x>W||y<0||y>H)continue;ctx.fillStyle=`rgba(132,158,99,${f.a*.35})`;ctx.beginPath();ctx.ellipse(x,y,2,1.2,-.4,0,TAU);ctx.fill()}}
  function drawFoliage(f){const colors=['#293a28','#243728','#30402b','#263726'];ctx.globalAlpha=.88;ctx.fillStyle=colors[f.c];ctx.beginPath();ctx.ellipse(f.x+3,f.y+6,f.r*.72,f.r*.37,.35,0,TAU);ctx.fill();ctx.fillStyle=colors[(f.c+1)%4];ctx.beginPath();ctx.arc(f.x,f.y,f.r*.45,0,TAU);ctx.fill();if(f.r>22){ctx.fillStyle='rgba(155,176,112,.18)';ctx.beginPath();ctx.arc(f.x-5,f.y-5,2,0,TAU);ctx.fill()}ctx.globalAlpha=1}
  function drawPlayer(){ctx.save();ctx.translate(player.x,player.y);const moving=Math.hypot(player.vx,player.vy)>3,bob=moving?Math.sin(Date.now()/65)*2:Math.sin(Date.now()/240)*.8;ctx.fillStyle='rgba(3,8,4,.35)';ctx.beginPath();ctx.ellipse(0,15,16,7,0,0,TAU);ctx.fill();if(player.invuln>0&&Math.floor(Date.now()/65)%2===0)ctx.globalAlpha=.5;
    ctx.fillStyle='#b9aa78';ctx.beginPath();ctx.arc(0,-12+bob,9,0,TAU);ctx.fill();ctx.fillStyle='#40573c';ctx.beginPath();ctx.moveTo(-13,-12+bob);ctx.quadraticCurveTo(-10,-28+bob,0,-23+bob);ctx.quadraticCurveTo(13,-27+bob,13,-12+bob);ctx.lineTo(7,-14+bob);ctx.lineTo(1,-20+bob);ctx.lineTo(-6,-14+bob);ctx.closePath();ctx.fill();ctx.fillStyle='#61794c';ctx.beginPath();ctx.moveTo(-12,-7+bob);ctx.quadraticCurveTo(-15,2+bob,-12,14);ctx.lineTo(12,14);ctx.quadraticCurveTo(15,1+bob,12,-7+bob);ctx.quadraticCurveTo(0,1+bob,-12,-7+bob);ctx.fill();ctx.fillStyle='#c9d887';ctx.shadowColor='#d8ef93';ctx.shadowBlur=14;ctx.beginPath();ctx.ellipse(0,1+bob,3,7,0,0,TAU);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#242d22';ctx.fillRect(player.face>0?3:-6,-13+bob,3,2);ctx.restore()}
  function drawEnemy(e){ctx.save();ctx.translate(e.x,e.y);const b=Math.sin(e.phase)*2;ctx.fillStyle='rgba(0,0,0,.25)';ctx.beginPath();ctx.ellipse(0,e.r*.65,e.r*1.05,e.r*.48,0,0,TAU);ctx.fill();if(e.hit>0)ctx.globalAlpha=.65;
    if(e.type==='mote'){ctx.fillStyle=e.color;ctx.beginPath();ctx.ellipse(0,b,e.r*1.05,e.r*.82,0,0,TAU);ctx.fill();ctx.fillStyle='#e4e6b1';ctx.fillRect(-4,-2,2,3);ctx.fillRect(3,-2,2,3);ctx.fillStyle='#34432f';ctx.fillRect(-3,-1,1,1);ctx.fillRect(4,-1,1,1)}
    else if(e.type==='bat'){ctx.fillStyle=e.color;ctx.beginPath();ctx.moveTo(-e.r,0);ctx.quadraticCurveTo(-e.r*2,-e.r*1.5,-e.r*.5,-e.r*.4);ctx.quadraticCurveTo(0,-e.r*1.2,e.r*.5,-e.r*.4);ctx.quadraticCurveTo(e.r*2,-e.r*1.5,e.r,0);ctx.quadraticCurveTo(0,e.r*1.3,-e.r,0);ctx.fill();ctx.fillStyle='#f0daae';ctx.fillRect(-3,-2,2,2);ctx.fillRect(2,-2,2,2)}
    else if(e.type==='brute'){ctx.fillStyle=e.color;ctx.beginPath();ctx.roundRect(-e.r*.8,-e.r*.8+b,e.r*1.6,e.r*1.6,7);ctx.fill();ctx.fillStyle='#e9cd9f';ctx.beginPath();ctx.moveTo(-9,-12+b);ctx.lineTo(-15,-21+b);ctx.lineTo(-5,-16+b);ctx.fill();ctx.beginPath();ctx.moveTo(9,-12+b);ctx.lineTo(15,-21+b);ctx.lineTo(5,-16+b);ctx.fill();ctx.fillRect(-7,-3,3,3);ctx.fillRect(4,-3,3,3)}
    else if(e.type==='boss'){ctx.rotate(Math.sin(e.phase)*.08);ctx.fillStyle=e.color;ctx.beginPath();ctx.arc(0,0,e.r,0,TAU);ctx.fill();ctx.fillStyle='#6b4040';for(let j=0;j<7;j++){const a=j/7*TAU;ctx.beginPath();ctx.moveTo(Math.cos(a)*e.r*.7,Math.sin(a)*e.r*.7);ctx.lineTo(Math.cos(a)*e.r*1.35,Math.sin(a)*e.r*1.35);ctx.lineTo(Math.cos(a+.3)*e.r*.7,Math.sin(a+.3)*e.r*.7);ctx.fill()}ctx.fillStyle='#f4dd9a';ctx.shadowColor='#ffcc75';ctx.shadowBlur=10;ctx.fillRect(-11,-6,6,6);ctx.fillRect(6,-6,6,6);ctx.shadowBlur=0;ctx.fillStyle='#523639';ctx.fillRect(-7,9,14,4);ctx.fill()}
    else {ctx.fillStyle=e.color;ctx.beginPath();ctx.arc(0,0,e.r,0,TAU);ctx.fill();ctx.fillStyle='#e3d5a5';ctx.beginPath();ctx.arc(-5,-2,3,0,TAU);ctx.arc(5,-2,3,0,TAU);ctx.fill();ctx.fillStyle='#453629';ctx.fillRect(-6,-3,2,2);ctx.fillRect(4,-3,2,2);ctx.fillStyle='#6b4c37';ctx.beginPath();ctx.moveTo(-6,-11);ctx.lineTo(-8,-20);ctx.lineTo(-1,-13);ctx.moveTo(6,-11);ctx.lineTo(10,-19);ctx.lineTo(2,-13);ctx.fill()}
    if(e.hp<e.maxHp||e.boss){const bw=e.boss?70:30,by=-e.r-9;ctx.fillStyle='rgba(10,14,10,.75)';ctx.fillRect(-bw/2,by,bw,3);ctx.fillStyle=e.boss?'#e98772':'#d9e29b';ctx.fillRect(-bw/2,by,bw*clamp(e.hp/e.maxHp,0,1),3)}ctx.restore()}
  function drawProjectile(p){ctx.save();ctx.translate(p.x,p.y);ctx.rotate(Math.atan2(p.vy,p.vx));ctx.fillStyle='#d9e794';ctx.shadowColor='#d6ef8a';ctx.shadowBlur=10;ctx.beginPath();ctx.moveTo(8,0);ctx.lineTo(-5,-3);ctx.lineTo(-3,0);ctx.lineTo(-5,3);ctx.closePath();ctx.fill();ctx.restore()}
  function drawGem(g){g.phase+=.06;ctx.save();ctx.translate(g.x,g.y+Math.sin(g.phase)*2);ctx.rotate(Math.PI/4);ctx.shadowColor='#d5ec8e';ctx.shadowBlur=12;ctx.fillStyle='#d8e995';ctx.fillRect(-3,-3,6,6);ctx.restore()}
