  $('startBtn').addEventListener('click',startGame);$('retryBtn').addEventListener('click',startGame);$('menuBtn').addEventListener('click',showMenu);ui.pauseBtn.addEventListener('click',pause);$('resumeBtn').addEventListener('click',pause);$('soundBtn').addEventListener('click',()=>{soundOn=!soundOn;$('soundBtn').textContent=soundOn?'♫':'♩';$('soundBtn').style.color=soundOn?'#d8e69a':'#a9aa91';if(soundOn)playTone(520,.1)});$('dashBtn').addEventListener('pointerdown',e=>{e.preventDefault();if(state!=='playing'||dashClock>0)return;dashClock=2.2;player.invuln=.38;const vx=touchMove.x||player.face,vy=touchMove.y;player.x+=vx*player.dashPower*115;player.y+=vy*player.dashPower*115;burst(player.x,player.y,'#d9e995',12);playTone(720,.1)});
